import React from 'react';

import { useNavigate } from 'react-router-dom';

import BGU from '@components/BGU';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

import { getAllProducts } from '../@services/products.service';
import { IProduct } from '../@types/products.types';
import { addProductInModalAsync } from '../components/ProductAddModal/productAddModalHelper';

const ProductsListPage: React.FC = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IProduct[]>([]);

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getAllProducts();
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs data={[{ href: '/products', text: 'Продукты', active: true }]} />

      <PohContainer>
        <PageHeader title="Продукты">
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={async () => {
              const newItem = await addProductInModalAsync();
              notificationHelper.success('Добавлено');
              setData((cur) => [...cur, newItem]);
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>

        <div>
          <PohList
            flush
            data={data.map((product) => {
              return {
                key: product.id,
                action: true,
                onClick: () => {
                  navigate(`/products/${product.id}`);
                },
                children: (
                  <div className="d-flex align-items-center ms-n2 ny-n3">
                    <div>
                      <strong title={product.name}>{product.name}</strong>
                    </div>
                    <BGU
                      portion={round(100, 0)}
                      energy={round(product.energy, 0)}
                      protein={round(product.protein, 0)}
                      fat={round(product.fat, 0)}
                      carbohydrates={round(product.carbs, 0)}
                      unit="в 100г"
                      className="ms-auto"
                    />
                  </div>
                ),
              };
            })}
          />
        </div>
      </PohContainer>
    </div>
  );
};

export default ProductsListPage;
